VALUES ($1, $2, $3::int, $4::jsonb, $5::jsonb, $6, 'nightly')
RETURNING id, table_name, row_count;

WITH keep AS (
  SELECT DISTINCT ON (table_name) id FROM n8n_data_table_backups
  WHERE label = 'nightly' ORDER BY table_name, backed_up_at DESC
), del AS (
  DELETE FROM n8n_data_table_backups
  WHERE backed_up_at < now() - make_interval(days => $1::int) AND id NOT IN (SELECT id FROM keep)
  RETURNING 1
)
SELECT count(*)::int AS rows_deleted FROM del;

