// One email for the whole run. WARNING when a table lost too many rows or disappeared since the last backup.
const s = $('Backup Settings').first().json;
const deleted = $('Delete Expired Snapshots').first().json.rows_deleted ?? 0;
const rows = $input.all().map((i) => i.json).filter((r) => r.table_name !== undefined);
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const when = (v) => (v ? DateTime.fromISO(String(v)).setZone($now.zoneName).toFormat('yyyy-LL-dd HH:mm') : '-');
const limit = Number(s.shrink_warning_percent) || 20;
const problems = [];
const lines = rows.map((r) => {
  const prev = r.previous_row_count === null || r.previous_row_count === undefined ? null : Number(r.previous_row_count);
  let now = r.row_count === null || r.row_count === undefined ? null : Number(r.row_count);
  let change = 'first backup';
  if (r.missing) { change = 'table deleted or renamed'; problems.push(r.table_name + ' (deleted)'); }
  else if (prev !== null) {
    const diff = now - prev;
    const pct = prev > 0 ? Math.round((-diff / prev) * 100) : 0;
    change = (diff >= 0 ? '+' : '') + diff + ' rows';
    if (diff < 0 && pct >= limit) { problems.push(r.table_name + ' (-' + pct + '%)'); change += ' (' + pct + '% fewer)'; }
  }
  const changed = r.changed === null || r.changed === undefined ? '-' : r.changed ? 'yes' : 'no';
  return '<tr><td>' + esc(r.table_name) + '</td><td>' + (now ?? '-') + '</td><td>' + (prev ?? '-') + '</td><td>' + when(r.previous_backed_up_at) + '</td><td>' + changed + '</td><td>' + esc(change) + '</td></tr>';
});
const current = rows.filter((r) => !r.missing);
const total = current.reduce((a, r) => a + Number(r.row_count), 0);
return [{ json: {
  to: s.alert_to,
  from: s.from_email,
  subject: problems.length
    ? 'WARNING: data table backup found lost data: ' + problems.join(', ')
    : 'Data table backup OK: ' + current.length + ' tables, ' + total + ' rows',
  html: (problems.length ? '<p><b>To recover, open the restore form and use the date of the last good backup (column "Last backup"), not today.</b></p>' : '') +
    '<table border="1" cellpadding="6" cellspacing="0"><tr><th>Table</th><th>Rows now</th><th>Rows last backup</th><th>Last backup</th><th>Content changed</th><th>Change</th></tr>' + lines.join('') + '</table>' +
    '<p>Expired snapshots deleted: ' + deleted + '. Warning threshold: ' + limit + '% fewer rows.</p>',
} }];

// The table is found by name, so a deleted and recreated table (new ID) can still be restored.
const name = String($('Find Backup').first().json.table_name).toLowerCase();
const table = $input.all().map((i) => i.json).find((t) => String(t.name || '').toLowerCase() === name);
return [{ json: { exists: Boolean(table), table_id: table ? table.id : null } }];

// Copy of the rows that are about to be replaced, saved before anything is changed.
const backup = $('Find Backup').first().json;
const tableId = $('Match Table Name').first().json.table_id;
const rows = $input.all().map((i) => i.json).filter((r) => r.id !== undefined);
return [{ json: { table_id: tableId, table_name: backup.table_name, columns: backup.columns ?? [], row_count: rows.length, rows } }];

